// UI translations. English is the source language and the default. The other catalogs are
// generated by mobile/tools/build_i18n.py: OrcaSlicer's own translations (localization/i18n)
// wherever OrcaSlicer has the same English text, machine translations for the rest
// (listed in each catalog's "_meta.machine_translated").

export const LANGUAGES = [
  { code: 'en', name: 'English' },
  { code: 'de', name: 'Deutsch' },
  { code: 'zh_CN', name: '简体中文' },
  { code: 'zh_TW', name: '繁體中文' },
  { code: 'ja', name: '日本語' },
  { code: 'es', name: 'Español' },
  { code: 'fr', name: 'Français' },
  { code: 'it', name: 'Italiano' },
  { code: 'nl', name: 'Nederlands' },
  { code: 'pt', name: 'Português' },
  { code: 'pl', name: 'Polski' },
  { code: 'cs', name: 'Čeština' },
  { code: 'hu', name: 'Magyar' },
  { code: 'sv', name: 'Svenska' },
  { code: 'nb', name: 'Norsk bokmål' },
  { code: 'da', name: 'Dansk' },
  { code: 'fi', name: 'Suomi' },
  { code: 'uk', name: 'Українська' },
  { code: 'ru', name: 'Русский' },
];

let strings = {};
let current = 'en';

/** Translates an English UI string; %1%, %2%… are replaced by the arguments (OrcaSlicer's style). */
export function t(text, ...args) {
  let out = strings[text] || text;
  args.forEach((a, i) => { out = out.split(`%${i + 1}%`).join(String(a)); });
  return out;
}

export const language = () => current;

export async function setLanguage(code) {
  if (!LANGUAGES.some((l) => l.code === code)) code = 'en';
  if (code === 'en') {
    strings = {};
  } else {
    const r = await fetch(`i18n/${code}.json`);
    if (!r.ok) throw new Error(`no catalog for ${code}`);
    strings = (await r.json()).strings;
  }
  current = code;
  document.documentElement.lang = code.replace('_', '-');
  applyI18n(document);
}

/** Fills elements marked data-i18n (text), data-i18n-title and data-i18n-aria (labels). */
export function applyI18n(root) {
  for (const el of root.querySelectorAll('[data-i18n]')) el.textContent = t(el.dataset.i18n);
  for (const el of root.querySelectorAll('[data-i18n-title]')) el.title = t(el.dataset.i18nTitle);
  for (const el of root.querySelectorAll('[data-i18n-aria]')) el.setAttribute('aria-label', t(el.dataset.i18nAria));
}
